import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'admin' }) {
  
  // 1️⃣ Admin Menu Items
  const adminMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items
  const teacherMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Activities', icon: '🧩' },
    { name: 'Upload Materials', icon: '📂' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Student Progress', icon: '📈' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 3️⃣ Student Menu Items
  const studentMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Study Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Class Timetable', icon: '🗓️' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 🔄 Role අනුව Menu Items Select කිරීම
  let menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;
  if (role === 'student') menuItems = studentMenuItems;

  return (
    <div style={styles.sidebar}>
      
      {/* 🟢 AuraPen Header */}
      <div style={styles.header}>
        <div style={styles.logoBox}>🖊️</div>
        <div>
          <h2 style={styles.title}>AuraPen</h2>
          <span style={styles.subTitle}>{role.toUpperCase()} PORTAL</span>
        </div>
      </div>

      <div style={styles.divider} />

      {/* 🟢 Navigation Items */}
      <div style={styles.menuContainer}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                ...styles.navButton,
                backgroundColor: isActive ? '#15803d' : 'transparent', // Exact Active Green
                fontWeight: isActive ? 'bold' : 'normal',
              }}
            >
              <span style={{ fontSize: '18px' }}>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          );
        })}
      </div>

      {/* 🔴 Bottom Logout Button (සමස්ත පල්ලෙහාම රතු පාටින්) */}
      <div style={styles.footer}>
        <button onClick={onLogoutClick} style={styles.logoutBtn}>
          <span>🚪</span> Logout
        </button>
      </div>

    </div>
  );
}

const styles = {
  sidebar: {
    width: '260px',
    minWidth: '260px',
    height: '100vh',
    backgroundColor: '#0f172a', // Clean Deep Dark Blue-Navy Tone
    color: '#ffffff',
    display: 'flex',
    flexDirection: 'column',
    boxSizing: 'border-box',
    borderRight: '1px solid #1e293b',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    padding: '20px 20px 10px 20px',
  },
  logoBox: {
    width: '40px',
    height: '40px',
    backgroundColor: '#15803d',
    borderRadius: '10px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '20px',
  },
  title: {
    margin: 0,
    fontSize: '20px',
    fontWeight: 'bold',
    color: '#ffffff',
  },
  subTitle: {
    fontSize: '10px',
    fontWeight: '700',
    color: '#4ade80',
    letterSpacing: '0.8px',
  },
  divider: {
    height: '1px',
    backgroundColor: '#1e293b',
    margin: '15px 20px',
  },
  menuContainer: {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
    padding: '0 15px',
    overflowY: 'auto',
  },
  navButton: {
    width: '100%',
    textAlign: 'left',
    padding: '12px 16px',
    color: '#ffffff',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    fontSize: '14.5px',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: '0.2s',
  },
  footer: {
    padding: '15px 15px 25px 15px',
    marginTop: 'auto',
    borderTop: '1px solid #1e293b',
  },
  logoutBtn: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#ef4444', // Red Logout Button
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontWeight: 'bold',
    fontSize: '14.5px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    boxShadow: '0 4px 8px rgba(239, 68, 68, 0.25)',
  },
};
